"""Guide operative dei cicli di lavoro, in sostituzione di esempi elementari."""
import json
from catalog_support import slug
from web_support import add,react_files,next_files

REPLACED={
'nodejs':['Generare UUID casuale','Rilevare runtime e piattaforma'],
'react':['Creare un contatore con stato','Controllare una select'],
'nextjs':['Aggiungere una rotta annidata','Definire titolo e descrizione statici'],
'aspnet':['Definire una Minimal API GET','Restituire testo semplice'],
'fastapi':['Definire endpoint GET JSON','Restituire testo semplice'],
'html-css':['Marcare date leggibili dalle macchine','Aggiungere link download per file generato'],
'django':['Selezionare soltanto le colonne necessarie','Verificare esistenza senza caricare oggetti'],
}

def launch(config):return json.dumps({'version':'0.2.0','configurations':[config]},indent=2)

def apply(b):
    if b.stack not in REPLACED:return
    ids={b.stack+'-'+slug(x) for x in REPLACED[b.stack]}
    assert len([r for r in b.recipes if r['id'] in ids])==2,(b.stack,ids)
    b.recipes[:]=[r for r in b.recipes if r['id'] not in ids]
    init,debug,icmd,dcmd,inote,dnote=content(b.stack)
    add(b,'Inizializzare ambiente e progetto '+b.stack,init,section='Inizializzazione',commands=icmd,note=inote,expected='L’applicazione si avvia localmente con il file di configurazione fornito. La versione della toolchain è verificabile dai comandi iniziali.',tags=[b.stack,'initialize','bootstrap','setup','environment','configuration'])
    section='Compilazione' if b.stack in ('react','nextjs','aspnet') else 'Debug'
    add(b,'Debug test e produzione '+b.stack,debug,section=section,commands=dcmd,note=dnote,expected='I test inclusi completano con esito positivo. La configurazione VSCode permette breakpoint sul sorgente; i comandi distinguono verifica, build e avvio di produzione.',tags=[b.stack,'debug','breakpoint','test','build','production','release'])

def content(stack):
    if stack=='nodejs':
        pkg={'name':'node-lifecycle','private':True,'version':'1.0.0','type':'module','scripts':{'start':'node src/main.mjs','dev':'node --watch src/main.mjs','test':'node --test','check':'node --check src/main.mjs'}}
        base={'package.json':json.dumps(pkg,indent=2),'.nvmrc':'24','src/main.mjs':"import{total}from'./pricing.mjs';console.log(total(10,3));",'src/pricing.mjs':"export function total(price,qty){if(!Number.isFinite(price)||price<0||!Number.isInteger(qty)||qty<1)throw Error('Valori invalidi');return price*qty}",'test/pricing.test.mjs':"import test from'node:test';import assert from'node:assert/strict';import{total}from'../src/pricing.mjs';test('totale',()=>assert.equal(total(10,3),30));test('quantità invalida',()=>assert.throws(()=>total(10,0)));"}
        debug={**base,'.vscode/launch.json':launch({'name':'Debug Node ESM','type':'node','request':'launch','program':'${workspaceFolder}/src/main.mjs','cwd':'${workspaceFolder}','skipFiles':['<node_internals>/**']})}
        return base,debug,'node --version\nnpm --version\nnpm install\nnpm start','npm test\nnpm run check\nnpm pack --dry-run','Esporta la cartella, verifica Node24+ e aprila nel terminale. package.json sceglie ESM e nomina avvio, watch e test; src separa il punto d’ingresso dalla funzione. npm install non richiede pacchetti esterni in questo esempio. npm start stampa30.','Apri la cartella in VSCode, imposta un breakpoint in pricing.mjs e premiF5. npm test esercita un caso valido e il rifiuto di quantità0; npm run check verifica sintassi. Node JavaScript non richiede compilazione: npm pack --dry-run mostra i file che verrebbero distribuiti senza pubblicare un pacchetto.'
    if stack=='react':
        base=react_files("export default function App(){return <h1>Progetto React inizializzato</h1>}")
        base['.nvmrc']='24';base['vite.config.js']="import{defineConfig}from'vite';export default defineConfig({server:{host:'127.0.0.1',port:5173,strictPort:true},build:{sourcemap:true}});"
        debug=react_files("import{total}from'./pricing.js';export default function App(){const[n,set]=useState(1);return <label>Quantità<input type='number' min='1' value={n} onChange={e=>set(Math.max(1,Number(e.target.value)))}/><output>{total(10,n)}€</output></label>}")
        debug.update({'vite.config.js':base['vite.config.js'],'src/pricing.js':"export function total(price,qty){if(qty<1)throw Error('Quantità positiva richiesta');return price*qty}",'test/pricing.test.mjs':"import test from'node:test';import assert from'node:assert/strict';import{total}from'../src/pricing.js';test('moltiplica',()=>assert.equal(total(10,3),30));test('rifiuta zero',()=>assert.throws(()=>total(10,0)));",'.vscode/launch.json':launch({'name':'React dev localhost','type':'pwa-chrome','request':'launch','url':'http://127.0.0.1:5173','webRoot':'${workspaceFolder}','sourceMaps':True})})
        return base,debug,'node --version\nnpm install\nnpm run dev','npm install\nnode --test\nnpm run build\nnpm run preview -- --host 127.0.0.1','Il package blocca React19.1.1/Vite7.1.7; index.html e src/main.jsx costituiscono l’ingresso. Avvia su localhost5173. strictPort evita di cambiare silenziosamente porta quando è occupata. Interrompi il server con Ctrl+C.','Per il debug avvia npm run dev in un terminale e premiF5 in VSCode con JavaScript Debugger. Metti il breakpoint nella funzione total. node --test verifica la logica; vite build crea dist con source map; vite preview serve il risultato su localhost4173. Preview è una verifica locale dell’artefatto, non un server pubblico da usare in produzione.'
    if stack=='nextjs':
        base=next_files({'app/page.js':"export default function Page(){return <h1>Next.js App Router pronto</h1>}"});base['.nvmrc']='24'
        debug=next_files({'lib/pricing.mjs':"export function total(price,qty){if(qty<1)throw Error('Quantità positiva richiesta');return price*qty}",'app/page.js':"import{total}from'../lib/pricing.mjs';export default function Page(){return <h1>Totale:{total(10,3)}</h1>}",'test/pricing.test.mjs':"import test from'node:test';import assert from'node:assert/strict';import{total}from'../lib/pricing.mjs';test('totale',()=>assert.equal(total(10,3),30));",'.vscode/launch.json':launch({'name':'Next server dev','type':'node','request':'launch','program':'${workspaceFolder}/node_modules/next/dist/bin/next','args':['dev','--hostname','127.0.0.1','--port','3000'],'cwd':'${workspaceFolder}','skipFiles':['<node_internals>/**'],'console':'integratedTerminal'})})
        return base,debug,'node --version\nnpm install\nnpm run dev','npm install\nnode --test\nnpm run build\nnpm start','La radice app contiene layout globale e pagina iniziale. Il layout genera html/body; il componente pagina resta server finché non serve interattività. Dopo npm install avvia su localhost3000. Mantieni package.json e il lock generato insieme per reinstallazioni ripetibili.','Apri la cartella in VSCode e avvia Next server dev conF5; richiamando la home puoi fermarti in lib/pricing.mjs. Per componenti client usa anche i breakpoint di DevTools del browser. node --test controlla la funzione, next build compila/prerenderizza, next start esegue il risultato di produzione localmente. Non utilizzare next dev per distribuire il servizio.'
    if stack=='aspnet':
        from web_aspnet import CSPROJ
        base={'Demo.csproj':CSPROJ,'Program.cs':'var b=WebApplication.CreateBuilder(args);var app=b.Build();app.MapGet("/health",()=>new{ok=true});app.Run();','global.json':'{"sdk":{"version":"10.0.400","rollForward":"latestFeature"}}'}
        debug={'Demo.csproj':CSPROJ.replace('</Project>','<ItemGroup><Compile Remove="tests/**/*.cs"/></ItemGroup></Project>'),'Program.cs':'var b=WebApplication.CreateBuilder(args);var app=b.Build();app.MapGet("/quote",(decimal price,int qty)=>{try{return Results.Ok(Pricing.Total(price,qty));}catch(ArgumentException){return Results.BadRequest();}});app.Run();','Pricing.cs':'public static class Pricing{public static decimal Total(decimal price,int qty){if(price<0||qty<1)throw new ArgumentException("Valori invalidi");return price*qty;}}','tests/Checks.csproj':'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><TargetFramework>net10.0</TargetFramework><OutputType>Exe</OutputType><ImplicitUsings>enable</ImplicitUsings></PropertyGroup><ItemGroup><ProjectReference Include="../Demo.csproj"/></ItemGroup></Project>','tests/Program.cs':'if(Pricing.Total(10,3)!=30)throw new Exception("Totale errato");try{Pricing.Total(10,0);throw new Exception("Eccezione attesa");}catch(ArgumentException){}Console.WriteLine("2controlli superati");','.vscode/launch.json':launch({'name':'Debug ASP.NET Core','type':'coreclr','request':'launch','preLaunchTask':'build','program':'${workspaceFolder}/bin/Debug/net10.0/Demo.dll','cwd':'${workspaceFolder}','env':{'ASPNETCORE_URLS':'http://127.0.0.1:5000'}}),'.vscode/tasks.json':json.dumps({'version':'2.0.0','tasks':[{'label':'build','type':'process','command':'dotnet','args':['build','Demo.csproj'],'problemMatcher':'$msCompile'}]})}
        return base,debug,'dotnet --info\ndotnet restore\ndotnet run --urls http://127.0.0.1:5000','dotnet run --project tests/Checks.csproj\ndotnet build Demo.csproj\ndotnet publish Demo.csproj -c Release -o artifacts/publish','global.json seleziona una feature bandSDK10 senza scaricarla automaticamente. Il progetto Web include soltanto il framework condiviso ASP.NET. Dopo restore avvia e richiama GET/health: ricevi ok=true. Per Linux/macOS usa gli stessi comandi dotnet nel terminale disponibile.','VSCode richiede l’estensione C# con debugger coreclr. F5 esegue il task build e avvia Demo.dll; metti un breakpoint in Pricing.Total e visita /quote?price=10&qty=3. Il piccolo runner tests/Checks.csproj verifica totale e quantità invalida senza NuGet aggiuntivi. Publish produce artifacts/publish: l’eseguibile framework dependent richiede runtime.NET10 sul computer di destinazione.'
    if stack=='fastapi':
        from web_fastapi import REQ
        base={'app.py':"from fastapi import FastAPI\napp=FastAPI()\n@app.get('/health')\ndef health(): return {'ok':True}\n",'requirements.txt':REQ}
        debug={'app.py':"from fastapi import FastAPI,HTTPException\napp=FastAPI()\n@app.get('/quote')\ndef quote(price:float,qty:int):\n    if price<0 or qty<1: raise HTTPException(422,'Valori invalidi')\n    return {'total':price*qty}\n",'requirements.txt':REQ,'test_app.py':"from fastapi.testclient import TestClient\nfrom app import app\nc=TestClient(app)\ndef test_total(): assert c.get('/quote?price=10&qty=3').json()['total']==30\ndef test_invalid(): assert c.get('/quote?price=10&qty=0').status_code==422\n",'.vscode/launch.json':launch({'name':'Debug FastAPI','type':'debugpy','request':'launch','module':'uvicorn','args':['app:app','--host','127.0.0.1','--port','8000'],'justMyCode':True})}
        return base,debug,'python --version\npython -m venv .venv\n.venv\\Scripts\\python -m pip install -r requirements.txt\n.venv\\Scripts\\python -m uvicorn app:app --host 127.0.0.1 --port 8000 --reload','.venv\\Scripts\\python -m pytest -q\n.venv\\Scripts\\python -m compileall -q app.py\n.venv\\Scripts\\python -m uvicorn app:app --host 127.0.0.1 --port 8000 --workers 2','Crea il venv e installa le versioni dichiarate senza modificare Python globale. app:app significa modulo app.py e istanza app. /docs espone OpenAPI; /health restituisce ok=true. Su Linux/macOS il Python del venv si trova in .venv/bin/python. --reload serve soltanto durante lo sviluppo.','In VSCode seleziona l’interprete .venv e installa l’estensione Python/Debugpy. F5 avvia uvicorn senza reload per mantenere il processo del debugger; imposta un breakpoint nella rotta quote. pytest usa TestClient senza server pubblico. Per un avvio multiprocesso locale usa --workers2 e nessun --reload; reverse proxy, TLS e gestione del servizio dipendono dall’ambiente di distribuzione.'
    if stack=='django':
        from web_django import BASE,SETTINGS
        base=dict(BASE)
        debug={**BASE,'notes/tests.py':"from django.test import TestCase\nfrom .models import Note\nclass ModelTests(TestCase):\n    def test_note(self):\n        n=Note.objects.create(title='Prova')\n        self.assertFalse(n.done)\n    def test_view(self):\n        self.assertEqual(self.client.get('/').status_code,200)\n",'config/wsgi.py':"import os\nos.environ.setdefault('DJANGO_SETTINGS_MODULE','config.settings')\nfrom django.core.wsgi import get_wsgi_application\napplication=get_wsgi_application()\n",'requirements.txt':BASE['requirements.txt']+'waitress==3.0.2\n','config/settings.py':SETTINGS+"\nSTATIC_ROOT=BASE_DIR/'staticfiles'\n",'.vscode/launch.json':launch({'name':'Debug Django','type':'debugpy','request':'launch','program':'${workspaceFolder}/manage.py','args':['runserver','127.0.0.1:8000','--noreload','--nothreading'],'django':True,'justMyCode':True})}
        return base,debug,'python -m venv .venv\n.venv\\Scripts\\python -m pip install -r requirements.txt\n.venv\\Scripts\\python manage.py migrate\n.venv\\Scripts\\python manage.py runserver 127.0.0.1:8000','.venv\\Scripts\\python manage.py test notes\n.venv\\Scripts\\python manage.py check --deploy\n.venv\\Scripts\\python manage.py collectstatic --noinput\n.venv\\Scripts\\python -m waitress --listen=127.0.0.1:8000 config.wsgi:application','Il progetto include settings, URL, modello e migrazione iniziale: migrate prepara SQLite senza generare sorgenti. runserver è un server di sviluppo. La chiave e DEBUG sono volutamente locali; per avviare un nuovo progetto di questo esempio basta esportare tutti i file e usare il venv indicato.','In VSCode seleziona .venv e Python/Debugpy; F5 avvia Django senza reloader e senza thread aggiuntivi. I test usano SQLite separato. check --deploy segnala esplicitamente DEBUG e chiave del laboratorio: prima di esporre pubblicamente imposta DEBUG=False, SECRET_KEY da ambiente e ALLOWED_HOSTS reali. collectstatic prepara gli asset; Waitress dimostra il processo WSGI locale, mentre TLS/statici pubblici richiedono il server previsto dal deployment.'
    if stack=='html-css':
        base={'index.html':'<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Progetto HTML</title><link rel="stylesheet" href="style.css"></head><body><h1>Pagina locale</h1><p id="result"></p><script type="module" src="app.js"></script></body></html>','style.css':'body{font:16px system-ui;max-width:60rem;margin:2rem auto;padding:1rem}','app.js':"import{total}from'./lib.js';document.getElementById('result').textContent='Totale:'+total(10,3);",'lib.js':"export function total(price,qty){if(qty<1)throw Error('Quantità positiva');return price*qty}",'package.json':'{"private":true,"type":"module"}'}
        debug={**base,'test.mjs':"import test from'node:test';import assert from'node:assert/strict';import{total}from'./lib.js';test('totale',()=>assert.equal(total(10,3),30));test('rifiuta zero',()=>assert.throws(()=>total(10,0)));",'.vscode/launch.json':launch({'name':'Debug pagina locale','type':'pwa-chrome','request':'launch','url':'http://127.0.0.1:8080','webRoot':'${workspaceFolder}'})}
        return base,debug,'python --version\npython -m http.server 8080 --bind 127.0.0.1','node --test test.mjs\nCompress-Archive -Path index.html,style.css,app.js,lib.js -DestinationPath site.zip -Force','Non occorre un framework: index.html collega CSS e modulo JavaScript locali. I moduli ESM vanno serviti da HTTP locale, non da file://. Il server Python serve soltanto questa cartella esportata su localhost8080; apri il browser e verifica Totale:30.','Avvia il server HTTP del primo esempio, poi F5 in VSCode con JavaScript Debugger oppure F12 nel browser; metti un breakpoint in lib.js e ricarica. node --test controlla la funzione senza DOM. Non esiste compilazione obbligatoria per questi file statici: lo ZIP include esattamente le risorse pubblicabili, escludendo test e configurazione debugger. Il server Python è soltanto di sviluppo.'
    raise KeyError(stack)
